import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
BASE=json.loads((HERE/'baseline-bank.json').read_text(encoding='utf8'))
QS=[q for q in BASE['questions'] if 'essay-10' in q['essayIds']]
SPECS={}
def put(n,ex,wrong,**extra):
 q=QS[n-1];assert n not in SPECS and len(wrong.split('|'))==3
 rs=iter(wrong.split('|'));cs=[dict(c,explanation=ex.split('。')[0]+'。' if c['id']==q['answerId'] else next(rs)) for c in q['choices']]
 SPECS[n]=dict(explanation=ex,summary=ex.split('。')[0]+'。',choices=cs,**extra)

put(1,'依本題以利為鋒利的限定，兵直接指兵器，非兵不利是否定兵器不鋒利這個根本敗因。資料也容兵器借指軍力，但不能忽略題目已指定的直接詞義。','軍隊是可延伸的軍事義，此題限定兵器鋒利。|戰爭是行為事件，不以鋒利形容。|戰術是作戰方法，後面的戰不善另談。')
